// Generates crates/sirene-core/src/math/unicode_data.rs: the characters KaTeX's parser reads
// specially (spec/latex-math.md, LMATH-12). Development tool: the generated file is checked in.
//
// Setup (once): the KaTeX checkout described in scripts/katex-fixtures.mjs, at tag v0.19.1.
// Run:
//   node --no-warnings scripts/katex-unicode.mjs
//
// Three tables: the accented letters it splits into a base and combining accents
// (`unicodeSymbols`), the command each combining accent stands for in text and math mode
// (`unicodeAccents`), and the subscript and superscript characters it reads as `_` or `^`
// followed by the plain character (`uSubsAndSups`). Adapted from KaTeX, MIT licensed, Copyright (c) 2013-2020 Khan Academy and
// other contributors; see THIRD-PARTY-NOTICES.

import { register } from "node:module";
import { writeFileSync } from "node:fs";

register("./katex-ts-loader.mjs", import.meta.url);
const { default: accented } = await import(new URL("../local/katex/src/unicodeSymbols.js", import.meta.url));
const { default: accents } = await import(new URL("../local/katex/src/unicodeAccents.js", import.meta.url));
const { uSubsAndSups } = await import(new URL("../local/katex/src/unicodeSupOrSub.ts", import.meta.url));

function chars(keys) {
  return [...new Set(keys)].map((k) => {
    if ([...k].length !== 1) throw new Error(`not one character: ${k}`);
    return k.codePointAt(0);
  }).sort((a, b) => a - b);
}

function list(name, doc, cps) {
  let out = `/// ${doc}\npub(super) const ${name}: &[char] = &[\n`;
  for (let i = 0; i < cps.length; i += 6) {
    out += "    " + cps.slice(i, i + 6).map((c) => `'\\u{${c.toString(16)}}',`).join(" ") + "\n";
  }
  return out + "];\n";
}

function lit(str) {
  let out = '"';
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (ch === '"' || ch === "\\") out += "\\" + ch;
    else if (cp >= 0x20 && cp < 0x7f) out += ch;
    else out += `\\u{${cp.toString(16)}}`;
  }
  return out + '"';
}
const ch = (c) => `'\\u{${c.codePointAt(0).toString(16)}}'`;

const decomposed = chars(Object.keys(accented)).map((cp) => String.fromCodePoint(cp));
const marks = chars(Object.keys(accents)).map((cp) => String.fromCodePoint(cp));

const out = `// Generated by scripts/katex-unicode.mjs from KaTeX 0.19.1. Do not edit.
// Adapted from KaTeX, MIT licensed, Copyright (c) 2013-2020 Khan Academy and other contributors;
// see THIRD-PARTY-NOTICES.

/// Accented letters KaTeX splits into a base letter and combining accents, sorted by letter.
pub(super) const DECOMPOSED: &[(char, &str)] = &[
${decomposed.map((c) => `    (${ch(c)}, ${lit(accented[c])}),`).join("\n")}
];

/// The command each combining accent stands for, sorted: the text-mode command, and the
/// math-mode command (empty if the accent has none).
pub(super) const ACCENT_COMMANDS: &[(char, &str, &str)] = &[
${marks.map((c) => `    (${ch(c)}, ${lit(accents[c].text)}, ${lit(accents[c].math ?? "")}),`).join("\n")}
];

${list("SCRIPTS", "Subscript and superscript characters KaTeX reads as a script, sorted.", chars(Object.keys(uSubsAndSups)))}`;
writeFileSync(new URL("../crates/sirene-core/src/math/unicode_data.rs", import.meta.url), out);
console.log(`${Object.keys(accented).length} accented, ${Object.keys(accents).length} accents, ${Object.keys(uSubsAndSups).length} scripts`);
